@app.post("/withdraw")
def withdraw(amount: int, x_race_delay: int = Header(0)):
    with Conn() as c:
        cur = c.cursor()
        cur.execute("select balance from wallet where id=1 for update")
        bal = cur.fetchone()[0]
        if bal < amount:
            raise HTTPException(409, "insufficient")
